122	func (s *APIV1Service) convertReactionsFromStoreWithCreators(ctx context.Context, reactions []*store.Reaction, creatorMap map[int32]*store.User) ([]*v1pb.Reaction, error) {
123		if len(reactions) == 0 {
124			return []*v1pb.Reaction{}, nil
125		}
126	
127		creatorIDs := make([]int32, 0, len(reactions))
128		for _, reaction := range reactions {
129			creatorIDs = append(creatorIDs, reaction.CreatorID)
130		}
131		creatorsByID, err := s.listUsersByIDWithExisting(ctx, creatorIDs, creatorMap)
132		if err != nil {
133			return nil, err
134		}
135	
136		reactionMessages := make([]*v1pb.Reaction, 0, len(reactions))
137		for _, reaction := range reactions {
138			reactionMessage, err := convertReactionFromStoreWithCreators(reaction, creatorsByID)
139			if err != nil {
140				if stderrors.Is(err, errReactionCreatorNotFound) {
141					slog.Warn("Skipping reaction with missing creator",
142						slog.Int64("reaction_id", int64(reaction.ID)),
143						slog.Int64("creator_id", int64(reaction.CreatorID)),
144						slog.String("content_id", reaction.ContentID),
145					)
146					continue
147				}
148				return nil, err
149			}
150			reactionMessages = append(reactionMessages, reactionMessage)
151		}
152		return reactionMessages, nil
153	}
